    }
  },
  "signal_basis": {
    "component_id": "C018.signal_basis",
    "value": "A predeclared safety threshold is crossed or telemetry fails during the experiment, triggering restoration of the original concurrency, cessation of further exposure, and recovery monitoring without terminating active exports.",
